mapper.select:
SELECT d.doc_no AS ref_key, CASE WHEN d.status IN ('REQ', 'REV', 'APV') THEN '결재 진행 또는 완료 문서' WHEN d.retention_until IS NOT NULL AND d.retention_until >= to_char(current_date, 'YYYYMMDD') THEN '보존기간' ELSE '문서 잠금' END AS target FROM tbl_document d WHERE d.co_cd = #{coCd} AND d.del_yn = 'N' AND d.idx IN
#{docIdx}
AND ( d.status IN ('REQ', 'REV', 'APV') OR ( d.retention_until IS NOT NULL AND d.retention_until >= to_char(current_date, 'YYYYMMDD') ) ) ORDER BY d.doc_no LIMIT 1

